(7540876, 1206898, 34171, '<td valign="top">Great shot and congratulations on your Blue Ribbon!<br/></td>', 'Great shot and congratulations on your Blue Ribbon!', '2017-10-25 12:30:12.000000', NULL, 0),
(7540878, 1206745, 34171, '<td valign="top">Congrats on the ribbon and the great shot.</td>', 'Congrats on the ribbon and the great shot.', '2017-10-25 12:31:28.000000', NULL, 0),
(7540880, 1206561, 34171, '<td valign="top">Awesome shot.  Congrats on the ribbon.</td>', 'Awesome shot.  Congrats on the ribbon.', '2017-10-25 12:32:08.000000', NULL, 0),
(7540896, 1206861, 124815, '<td valign="top">Stay true to yourself. If you want to be popular you lose yourself and will produce only more of the same stuff that gets the accolades.<br/>I marked you 7. I mostly liked the perspective. So there! I liked what other viewers objected to. Did not have time for comments but I would have said: here is a lovely page for a Jules Verne type of book (knowing nothing of the singer).</td>', 'Stay true to yourself. If you want to be popular you lose yourself and will produce only more of the same stuff that gets the accolades.I marked you 7. I mostly liked the perspective. So there! I liked what other viewers objected to. Did not have time for comments but I would have said: here is a lovely page for a Jules Verne type of book (knowing nothing of the singer).', '2017-10-25 13:23:58.000000', NULL, 0),
(7540897, 1206743, 124815, '<td valign="top">I marked it 10 - my favorite in the challenge. Gave me the chills; a very powerful image independently of the fact that I know nothing about the singer</td>', 'I marked it 10 - my favorite in the challenge. Gave me the chills; a very powerful image independently of the fact that I know nothing about the singer', '2017-10-25 13:26:30.000000', NULL, 0),
(7540899, 1206743, 30364, '<td valign="top">It''s OK.  Had I voted I''d have given it a 10, but that''s only 5 per tusk.  Still, two 5s is a nice pair.  Thank you.</td>', 'It''s OK.  Had I voted I''d have given it a 10, but that''s only 5 per tusk.  Still, two 5s is a nice pair.  Thank you.', '2017-10-25 13:38:07.000000', NULL, 0),
